use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,collections::BTreeMap};
const R:&str="/home/ubuntu/src/zopro-perf-work/loose-delta-sdk175";const Z:&str="/home/ubuntu/src/zk-tools/zopro";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let root=Path::new(R);let z=Path::new(Z);let m=read(z.join("docs/benchmarks/2026-10-29-balanced-kh-adoption/artifacts/production-source-manifest.json"));let a=read(root.join("source-audit.json"));let mut exact=0;let mut pins=BTreeMap::new();let parent=Path::new("/home/ubuntu/src/zopro-perf-work/loose-delta175/source");let mut field=0;
for(p,h)in m["source_files_sha256"].as_object().unwrap(){let original=fs::read(z.join(p)).unwrap();assert_eq!(hash(z.join(p)),h.as_str().unwrap());let path=root.join("source").join(p);let bytes=fs::read(&path).unwrap();let restored=if let Some(e)=a["edits"].get(p){let mut s=String::from_utf8(bytes.clone()).unwrap();if let Some(suffix)=e["suffix"].as_str(){s=s.strip_suffix(suffix).unwrap().into();}else{let after=e["after"].as_str().unwrap();assert_eq!(s.matches(after).count(),1);s=s.replacen(after,e["before"].as_str().unwrap(),1);}s.into_bytes()}else{bytes.clone()};assert_eq!(restored,original,"inverse {p}");if bytes==original{exact+=1;}if p.starts_with("crates/zopro-bn254/"){assert_eq!(bytes,fs::read(parent.join(p)).unwrap());field+=1;}pins.insert(p.clone(),hash(&path));}
assert_eq!(exact,170);assert_eq!(field,17);let child=a["child"].as_str().unwrap();assert_eq!(fs::read(root.join("source").join(child)).unwrap(),fs::read(parent.join(child)).unwrap());pins.insert(child.into(),hash(root.join("source").join(child)));assert_eq!(pins.len(),176);let msm=fs::read_to_string(root.join("source/crates/zopro-core/src/msm.rs")).unwrap();let simd=fs::read_to_string(root.join("source/crates/zopro-core/src/simd.rs")).unwrap();assert!(!msm.contains("mod caller_probe;"));assert_eq!(msm.matches("all(feature=\"ifma8\",zopro_loose_delta,").count(),2);assert_eq!(simd.matches("all(feature=\"ifma8\",zopro_loose_delta,").count(),1);let mut code=BTreeMap::new();for label in["control","candidate"]{let p=root.join(format!("native/{label}-sdk"));let receipt=read(root.join(format!("native/{label}/artifacts.json")));assert_eq!(hash(&p),receipt["binary_sha256"].as_str().unwrap());code.insert(label,json!({"binary":p,"sha256":hash(&p)}));}
fs::write(root.join("final-source-review.json"),serde_json::to_vec_pretty(&json!({"reverse175_exact":true,"source_files":176,"originals_exact":170,"field17_and_child_exact_qualified_component":true,"three_native_feature_guards_correct":true,"caller_adapter_absent":true,"private_hashes":pins,"code":code})).unwrap()).unwrap();println!("Independent SDK source review:176files170exact/inverse175;fieldqualificationexact;3featureguards;no caller adapter;SDK ELF receipts match");}
